function ETA-QUOTIENT-COEFFICIENTS(a, n):
    input : exponent vector a, degree bound n
    output: A[0..n] with A[j] = [q^j] prod_m (1-q^m)^{-b_m}

    # 1. divisor data by a sieve over multiples:  O(n log n)
    b[1..n] <- 0
    for each k in support(a):
        for m <- k, 2k, 3k, ... while m <= n:
            b[m] <- b[m] + a[k]

    # 2. twisted divisor sums sigma_b(j) = sum_{m | j} m b_m:  O(n log n)
    sigma[1..n] <- 0
    for m <- 1 to n:
        if b[m] != 0:
            w <- m * b[m]
            for j <- m, 2m, 3m, ... while j <= n:
                sigma[j] <- sigma[j] + w

    # 3. the recursion:  O(n^2) integer multiplications
    A[0] <- 1
    for k <- 1 to n:
        T <- sum over i in 0..k-1 of A[i] * sigma[k-i]
        assert T mod k = 0            # the recursion always divides exactly
        A[k] <- T / k
    return A

